// Keycloak コネクタ。
// 入力: {
//   operation: 'add' | 'change' | 'remove',
//   member: { id, email, name },
//   desired: ['group:team-alpha', ...],   // あるべき grant 集合(remove では空)
//   current: ['group:pm', ...]            // state に記録済みの grant 集合
// }
// 出力: { ok, applied: { added, removed }, enabled, detail }
//
// 冪等に作る(既に目標状態なら成功扱い)。リコンサイラが何度呼んでも同じ結果になる。
// 設計: docs/design/03-service-catalog.md#ハンドラの入出力インターフェース

const inp = $input.first()?.json ?? {};
const OPS = ['add', 'change', 'remove'];
if (!OPS.includes(inp.operation)) {
  throw new Error(`service-keycloak: 不正な operation: ${JSON.stringify(inp.operation)}`);
}
const member = inp.member ?? {};
if (!member.id || !member.email) {
  throw new Error('service-keycloak: member.id と member.email は必須です');
}

// grant は 'group:<名前>' 形式。それ以外は無視する(このサービスが解釈できる形だけ扱う)。
const toGroups = (list) => [...new Set((Array.isArray(list) ? list : [])
  .filter((g) => typeof g === 'string' && g.startsWith('group:'))
  .map((g) => g.slice('group:'.length)))];

const desiredGroups = inp.operation === 'remove' ? [] : toGroups(inp.desired);
const currentGroups = toGroups(inp.current);

const base = `${$env.KEYCLOAK_URL}/admin/realms/${$env.KEYCLOAK_REALM}`;
const nameParts = String(member.name ?? '').trim().split(/\s+/);

return [{ json: {
  base,
  operation: inp.operation,
  memberId: member.id,
  email: member.email,
  firstName: nameParts[0] ?? member.id,
  lastName: nameParts.slice(1).join(' ') || '-',
  desiredGroups,
  currentGroups,
  shouldBeEnabled: inp.operation !== 'remove',
}}];

// グループ名 → ID の対応表を作る(HTTP ノードが配列をアイテムに分割済み)。
const map = {};
for (const item of $input.all()) {
  const g = item.json;
  if (g && g.name && g.id) map[g.name] = g.id;
}
return [{ json: { groupMap: map } }];

// 実施すべき変更を「1操作1アイテム」に展開する。
// 後続の HTTP ノードがアイテムごとに実行するため、ループ辺が要らない。
// enabled の設定は常に含めるので、アイテムが 0 件になることはない。

const ctx = $('入力を検証する').first().json;
const groupMap = $('グループ表を作る').first().json.groupMap;
const user = $input.first()?.json;

if (!user || !user.id) {
  throw new Error(`service-keycloak: ユーザー ${ctx.memberId} の作成・取得ができませんでした`);
}

const unknown = ctx.desiredGroups.filter((g) => !groupMap[g]);
if (unknown.length > 0) {
  throw new Error(`service-keycloak: Keycloak に存在しないグループが指定されました: ${unknown.join(', ')}`);
}

const toAdd = ctx.desiredGroups.filter((g) => !ctx.currentGroups.includes(g));
const toRemove = ctx.currentGroups.filter((g) => !ctx.desiredGroups.includes(g) && groupMap[g]);

const ops = [];

// 1. 有効/無効(キルスイッチ)。常に実行して目標状態に寄せる。
ops.push({
  kind: 'enabled',
  method: 'PUT',
  url: `${ctx.base}/users/${user.id}`,
  body: { enabled: ctx.shouldBeEnabled },
});

// 2. グループの付与・剥奪
for (const g of toAdd) {
  ops.push({ kind: 'group-add', group: g, method: 'PUT', url: `${ctx.base}/users/${user.id}/groups/${groupMap[g]}`, body: {} });
}
for (const g of toRemove) {
  ops.push({ kind: 'group-remove', group: g, method: 'DELETE', url: `${ctx.base}/users/${user.id}/groups/${groupMap[g]}`, body: {} });
}

// 3. 削除時はセッションも失効させる(停止だけでは既存セッションが残るため)
if (ctx.operation === 'remove') {
  ops.push({ kind: 'logout', method: 'POST', url: `${ctx.base}/users/${user.id}/logout`, body: {} });
}

return ops.map((json) => ({ json: { ...json, userId: user.id } }));

// 各操作の成否をまとめて返す。1つでも失敗したら ok: false。
const ctx = $('入力を検証する').first().json;
const ops = $('操作を組み立てる').all().map((i) => i.json);
const results = $input.all().map((i) => i.json);

const failures = [];
results.forEach((res, i) => {
  const err = res?.error;
  if (err) failures.push(`${ops[i]?.kind ?? '?'}: ${err.message ?? JSON.stringify(err).slice(0, 120)}`);
});

const added = ops.filter((o) => o.kind === 'group-add').map((o) => o.group);
const removed = ops.filter((o) => o.kind === 'group-remove').map((o) => o.group);

if (failures.length > 0) {
  return [{ json: {
    ok: false,
    detail: `service-keycloak: ${ctx.memberId} の更新で失敗: ${failures.join(' / ')}`,
    applied: { added: [], removed: [] },
  }}];
}

return [{ json: {
  ok: true,
  applied: { added, removed },
  enabled: ctx.shouldBeEnabled,
  grants: ctx.desiredGroups.map((g) => `group:${g}`),
  detail: `${ctx.memberId}: 付与 ${added.length} 件 / 剥奪 ${removed.length} 件 / enabled=${ctx.shouldBeEnabled}`,
}}];
